def comps_nz(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=0 and not seen[i][j]:
                st=[(i,j)]; cs=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; cs.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]!=0 and not seen[ny][nx]:
                                st.append((ny,nx))
                out.append(cs)
    return out
