def rule(A,B):
    # A cells inside B's bbox that are not in B, cropped to B bbox
    bT=(min(y for y,_ in B),min(x for _,x in B))
    bh=max(y for y,_ in B)-bT[0]+1; bw=max(x for _,x in B)-bT[1]+1
    cells=[(y,bT[1]+(x-bT[1])) for y,x in A if bT[0]<=y<bT[0]+bh and bT[1]<=x<bT[1]+bw and (y,x) not in B]
    if not cells: return None
    ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
    cy=min(ys); cx=min(xs)
    out=[[8 if (i,j) in {(y-cy,x-cx) for y,x in cells} else 0 for j in range(max(x for _,x in cells)-cx+1)] for i in range(max(y for y,_ in cells)-cy+1)]
    return out

